const aiResponse = $input.first().json;
const extractedData = items[0].json || {};

// Funzione per andare a capo dopo N caratteri
function wrapText(text, maxLength = 80) {
  if (!text) return text;

  const words = text.split(' ');
  const lines = [];
  let currentLine = '';

  words.forEach(word => {
    if ((currentLine + word).length > maxLength) {
      lines.push(currentLine.trim());
      currentLine = word + ' ';
    } else {
      currentLine += word + ' ';
    }
  });

  if (currentLine.trim()) {
    lines.push(currentLine.trim());
  }

  return lines.join('\n');
}

// Il testo è un JSON stringificato, dobbiamo fare il parse
let summary = "No summary generated";
try {
  const textContent = aiResponse.candidates?.[0]?.content?.parts?.[0]?.text;
  if (textContent) {
    // Parse del JSON contenuto nel text
    const parsedText = JSON.parse(textContent);

    // Caso 1: Se è un oggetto con campo "resumen"
    if (parsedText.resumen) {
      summary = wrapText(parsedText.resumen);
    }
    // Caso 2: Se è un array (come nel caso dell'articolo scientifico)
    else if (Array.isArray(parsedText) && parsedText.length > 0) {
      const doc = parsedText[0];
      // Crea un riassunto combinando i campi principali
      let summaryParts = [];

      if (doc.title) {
        summaryParts.push(`**${doc.title}**\n`);
      }
      if (doc.authors) {
        summaryParts.push(`*Autores: ${doc.authors.join(', ')}*\n`);
      }
      if (doc.abstract) {
        summaryParts.push(wrapText(doc.abstract) + '\n');
      }
      if (doc.conclusions) {
        summaryParts.push(`**Conclusiones:**\n${wrapText(doc.conclusions)}`);
      }

      summary = summaryParts.join('\n');
    }
    // Caso 3: Se è un oggetto generico
    else if (typeof parsedText === 'object') {
      const content = parsedText.abstract || parsedText.summary || 
                     parsedText.text || JSON.stringify(parsedText, null, 2);
      summary = wrapText(content);
    }
  }
} catch (e) {
  // Se non è JSON, usa il testo direttamente
  const rawText = aiResponse.candidates?.[0]?.content?.parts?.[0]?.text ?? 
                  "No summary generated";
  summary = wrapText(rawText);
}

// Stats — se non esistono, valori di default
const stats = extractedData.stats || {};
const wordCount = stats.word_count ?? 0;
const charCount = stats.char_count ?? 0;

const output = {
  success: true,
  documento_original: {
    nombre: extractedData.file_type ?? "desconocido",
    palabras: wordCount,
    caracteres: charCount
  },
  resumen_ejecutivo: summary,
  metadata: {
    fecha_generacion: new Date().toISOString(),
    modelo_ia: aiResponse.modelVersion,
    tokens_usados: aiResponse.usageMetadata
  },
  markdown: `# Resumen Ejecutivo

${summary}

---

**Documento Original:** ${wordCount} palabras
**Fecha:** ${new Date().toLocaleDateString('es-ES')}
**Generado con:** Google Gemini (${aiResponse.modelVersion})`
};

return output;

const input = $input.first().json;

// Converti il markdown in file binario
const markdownContent = input.markdown || '';
const buffer = Buffer.from(markdownContent, 'utf-8');

return {
  json: input,
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'text/markdown',
      fileName: `resumen_${new Date().toISOString().split('T')[0]}.md`,
      fileExtension: 'md'
    }
  }
};
